import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// Livro físico · "Como Superar o Luto com Hipnose" (Edinardo Passos). Motion vertical sobre a narração (ElevenLabs, o locutor, 47,1 s).
// Jeito: motion (pouco material: capa em PNG e dois mockups em vídeo). O problema (0–19,4 s) é desenhado e genérico: telefone
// de madrugada, relógio que para, mensagem que não chega, a palavra LUTO. O livro só estreia em "No livro".
// Identidade da capa e do site: preto, vermelho #F31616, branco; Anton em caixa alta (título da capa) + Poppins.
// Limpo: fundo liso preto, brilho vermelho só atrás do destaque; o texto entra e fica parado, o movimento fica nos objetos.
// Tempos = tempos da narração; o vídeo começa LEAD antes.

const { fontFamily: AN } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: PO } = loadPoppins("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const LF_FPS = 30;
const LEAD = 0.3;
const VEND = 47.12;
const TAIL = 2.4;
export const LF_FRAMES = Math.round((LEAD + VEND + TAIL) * LF_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + LEAD) * LF_FPS));

const BG = "#0A0A0A";
const CARD = "#161616";
const LINE = "#2A2A2A";
const RED = "#F31616";
const WHITE = "#FFFFFF";
const MUTED = "#A3A3A3";
const SHADOW = "0 40px 90px rgba(0,0,0,0.6), 0 6px 18px rgba(0,0,0,0.4)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

// trocas de cena (tempo da voz)
const T2 = 5.6, T2B = 10.15, T3 = 13.25, T4 = 19.4, T4B = 27.5, T5 = 30.8, T5B = 34.0, T6 = 37.95, T7 = 41.85;

// texto: entra com impulso (desfoque + escala), assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 12).toFixed(1)}px)`,
    transform: `scale(${(1.12 - 0.12 * e).toFixed(4)})`,
  };
};
// palavra que bate: entra grande e assenta com tranco
const slam = (t: number, at: number, out?: number): React.CSSProperties => {
  const e = k(t, at, 0.28);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return { opacity: Math.min(1, e * 3) * (1 - o), transform: `scale(${(1.7 - 0.7 * e).toFixed(4)})`, filter: `blur(${(o * 12).toFixed(1)}px)` };
};

const Row: React.FC<{ top: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", ...style }}>{children}</div>
);
const anton = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: AN, fontSize: size, lineHeight: 1.08, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "0.005em" });
const pops = (size: number, color = WHITE, weight = 600): React.CSSProperties => ({ fontFamily: PO, fontWeight: weight, fontSize: size, lineHeight: 1.2, color, whiteSpace: "nowrap", letterSpacing: "-0.01em" });

// barra vermelha da capa, que corre da esquerda para a direita
const Bar: React.FC<{ t: number; at: number; w: number; top: number; h?: number }> = ({ t, at, w, top, h = 16 }) => (
  <div style={{ position: "absolute", left: 540 - w / 2, top, width: w * interpolate(t, [at, at + 0.35], [0, 1], { ...cl, easing: INOUT }), height: h, background: RED }} />
);
// brilho vermelho só atrás do destaque
const Glow: React.FC<{ x: number; y: number; r: number; o: number }> = ({ x, y, r, o }) => (
  <div style={{ position: "absolute", left: x - r, top: y - r, width: 2 * r, height: 2 * r, borderRadius: r, background: "radial-gradient(circle, rgba(243,22,22,0.34) 0%, rgba(243,22,22,0.10) 42%, rgba(243,22,22,0) 70%)", opacity: o }} />
);

// ───────── ícones ─────────
const IcoCall: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M6.6 10.8c1.4 2.8 3.8 5.1 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1C10.6 21 3 13.4 3 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1l-2.3 2.2z" /></svg>
);
const IcoUser: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><circle cx={12} cy={8} r={4.2} /><path d="M3.5 21c.8-4.4 4.2-7 8.5-7s7.7 2.6 8.5 7z" /></svg>
);
const IcoHead: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2.2} strokeLinecap="round"><path d="M4 15v-3a8 8 0 0 1 16 0v3" /><rect x={3} y={14} width={4.5} height={7} rx={1.6} fill={c} /><rect x={16.5} y={14} width={4.5} height={7} rx={1.6} fill={c} /></svg>
);
const IcoDoc: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2.2} strokeLinejoin="round" strokeLinecap="round"><path d="M6 2.8h8l4.5 4.5V21H6z" /><path d="M14 2.8v4.5h4.5" /><path d="M9 12.5h6M9 16h6" /></svg>
);
const IcoPlay: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={2.2} strokeLinejoin="round"><rect x={2.5} y={4.5} width={19} height={15} rx={3} /><path d="M10 9v6l5-3z" fill={c} /></svg>
);
const IcoTruck: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M2 5h12v10H2z" /><path d="M14 8h4l3.5 4v3H14z" /><circle cx={6} cy={17.5} r={2.3} fill={c} stroke={BG} strokeWidth={1.2} /><circle cx={17.5} cy={17.5} r={2.3} fill={c} stroke={BG} strokeWidth={1.2} /></svg>
);
const IcoShield: React.FC<{ s: number; c: string; draw: number }> = ({ s, c, draw }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none"><path d="M12 2.5l8 3v6c0 5-3.4 8.6-8 10-4.6-1.4-8-5-8-10v-6z" fill={c} /><path d="M8 12l3 3 5-6" stroke={WHITE} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round" strokeDasharray={14} strokeDashoffset={14 * (1 - draw)} /></svg>
);

// ───────── cena 1 · uma ligação de madrugada ─────────
const ACC = 1.3, DROP = 4.45;
const Phone: React.FC<{ t: number }> = ({ t }) => {
  const W = 460, H = 920;
  const inn = pop(t, -0.3, 0.45);
  const ringing = t < ACC;
  // vibra em rajadas, como o celular tocando
  const burst = ringing ? (Math.sin((t + 0.3) * Math.PI * 2.4) > -0.2 ? 1 : 0.15) : 0;
  const vib = Math.sin(t * 95) * 7 * burst;
  const accP = interpolate(t, [ACC - 0.08, ACC, ACC + 0.18], [0, 1, 0], cl);
  const drop = interpolate(t, [DROP, DROP + 0.75], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
  const cam = 0.94 + 0.08 * lin(t, 0, DROP);
  const secs = Math.max(0, Math.floor(t - ACC));
  return (
    <div style={{ position: "absolute", left: 540 - W / 2, top: 640, width: W, height: H, opacity: Math.min(1, inn * 2) * (1 - 0.55 * drop), filter: `blur(${(drop * 7).toFixed(1)}px)`, transform: `translate(${vib.toFixed(1)}px, ${((1 - inn) * 260 + drop * 400).toFixed(1)}px) rotate(${(vib * 0.25 - drop * 26).toFixed(2)}deg) scale(${(cam * (0.7 + 0.3 * inn) * (1 - 0.08 * drop)).toFixed(4)})` }}>
      {/* ondas do toque */}
      {ringing
        ? [0, 1, 2].map((j) => {
            const u = ((t + 0.3) * 1.6 + j / 3) % 1;
            return <div key={j} style={{ position: "absolute", left: -40 - u * 120, right: -40 - u * 120, top: 80 - u * 120, bottom: 80 - u * 120, borderRadius: 120, border: `4px solid ${RED}`, opacity: (1 - u) * 0.55 * Math.min(1, inn * 2) }} />;
          })
        : null}
      <div style={{ position: "absolute", inset: 0, borderRadius: 74, background: "#050505", border: `3px solid ${LINE}`, boxShadow: SHADOW, overflow: "hidden" }}>
        <div style={{ position: "absolute", inset: 14, borderRadius: 62, background: "linear-gradient(180deg, #1C1C1C 0%, #0E0E0E 100%)", overflow: "hidden" }}>
          <div style={{ position: "absolute", left: W / 2 - 14 - 60, top: 18, width: 120, height: 34, borderRadius: 17, background: "#000" }} />
          <div style={{ position: "absolute", left: 0, right: 0, top: 86, textAlign: "center", ...pops(112, WHITE, 500), letterSpacing: "-0.03em" }}>03:12</div>
          <div style={{ position: "absolute", left: 0, right: 0, top: 236, textAlign: "center", ...pops(30, MUTED, 500) }}>{ringing ? "chamada recebida" : `00:0${Math.min(9, secs)}`}</div>
          <div style={{ position: "absolute", left: (W - 28) / 2 - 80, top: 310, width: 160, height: 160, borderRadius: 80, background: "#2B2B2B", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <IcoUser s={100} c="#6E6E6E" />
          </div>
          <div style={{ position: "absolute", left: 0, right: 0, top: 500, textAlign: "center", ...pops(36, WHITE, 600) }}>Número desconhecido</div>
          {!ringing ? (
            <div style={{ position: "absolute", left: 0, right: 0, top: 580, height: 80, display: "flex", alignItems: "center", justifyContent: "center", gap: 10, opacity: k(t, ACC + 0.2, 0.3) * (1 - lin(t, 3.6, 4.0)) }}>
              {[...Array(9)].map((_, j) => (
                <div key={j} style={{ width: 10, borderRadius: 5, background: WHITE, height: 12 + 56 * Math.abs(Math.sin(t * 7.3 + j * 1.9) * Math.sin(t * 3.1 + j * 0.7)) }} />
              ))}
            </div>
          ) : null}
          {/* botões: recusar e atender; depois de atender, só desligar */}
          {ringing ? (
            <>
              <div style={{ position: "absolute", left: 62, top: 700, width: 116, height: 116, borderRadius: 58, background: RED, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <div style={{ transform: "rotate(135deg)", display: "flex" }}><IcoCall s={60} c={WHITE} /></div>
              </div>
              <div style={{ position: "absolute", right: 62, top: 700, width: 116, height: 116, borderRadius: 58, background: "#22C55E", display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(1 + 0.08 * Math.max(0, Math.sin((t + 0.3) * 9)) - 0.15 * accP).toFixed(3)})` }}>
                <IcoCall s={60} c={WHITE} />
              </div>
            </>
          ) : (
            <div style={{ position: "absolute", left: (W - 28) / 2 - 58, top: 700, width: 116, height: 116, borderRadius: 58, background: RED, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${(0.6 + 0.4 * pop(t, ACC, 0.35)).toFixed(3)})` }}>
              <div style={{ transform: "rotate(135deg)", display: "flex" }}><IcoCall s={60} c={WHITE} /></div>
            </div>
          )}
          {/* clarão ao atender */}
          <div style={{ position: "absolute", inset: 0, background: WHITE, opacity: accP * 0.25 }} />
        </div>
      </div>
    </div>
  );
};
const Ligacao: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BG }}>
    <Glow x={540} y={1100} r={620} o={0.7 * (1 - lin(t, DROP, DROP + 0.8))} />
    <Phone t={t} />
    {t < 2.3 ? <Row top={250}><div style={{ ...anton(150), ...slam(t, 0.12, 2.05) }}>Uma ligação.</div></Row> : null}
    {t >= 2.25 ? (
      <>
        <Row top={200}><div style={{ ...anton(124), ...blurIn(t, 2.33) }}>E a vida muda</div></Row>
        <Row top={350}><div style={{ ...anton(150, RED), ...slam(t, 4.41) }}>pra sempre.</div></Row>
      </>
    ) : null}
  </AbsoluteFill>
);

// ───────── cena 2a · de repente: o relógio para ─────────
const STOP = 6.84;
const Repente: React.FC<{ t: number }> = ({ t }) => {
  const inn = pop(t, T2 - 0.05, 0.5);
  // ponteiro corre e para seco em "de repente"
  const spin = t < STOP ? (t - T2) * 900 : (STOP - T2) * 900 + Math.sin((t - STOP) * 40) * 6 * Math.max(0, 1 - (t - STOP) / 0.4);
  const minute = t < STOP ? (t - T2) * 75 : (STOP - T2) * 75;
  const cam = 1 + 0.16 * lin(t, T2, T2B);
  const R = 190;
  return (
    <AbsoluteFill style={{ background: BG }}>
      <div style={{ position: "absolute", left: 540 - R, top: 400, width: 2 * R, height: 2 * R, opacity: Math.min(1, inn * 2), transform: `scale(${((0.6 + 0.4 * inn) * cam * (1 + 0.06 * (t > STOP ? 1 - k(t, STOP, 0.35) : 0))).toFixed(4)}) rotate(${(-6 * lin(t, STOP, T2B)).toFixed(2)}deg)` }}>
        <svg width={2 * R} height={2 * R} viewBox={`${-R} ${-R} ${2 * R} ${2 * R}`}>
          <circle r={R - 8} fill={CARD} stroke={WHITE} strokeWidth={10} />
          {[...Array(12)].map((_, i) => {
            const a = (i / 12) * 2 * Math.PI;
            return <line key={i} x1={Math.sin(a) * (R - 40)} y1={-Math.cos(a) * (R - 40)} x2={Math.sin(a) * (R - 24)} y2={-Math.cos(a) * (R - 24)} stroke={i % 3 ? "#5A5A5A" : WHITE} strokeWidth={i % 3 ? 5 : 8} strokeLinecap="round" />;
          })}
          <line x1={0} y1={0} x2={0} y2={-(R - 90)} stroke={WHITE} strokeWidth={12} strokeLinecap="round" transform={`rotate(${minute.toFixed(1)})`} />
          <line x1={0} y1={30} x2={0} y2={-(R - 48)} stroke={RED} strokeWidth={7} strokeLinecap="round" transform={`rotate(${spin.toFixed(1)})`} />
          <circle r={14} fill={RED} />
        </svg>
      </div>
      <Row top={900}><div style={{ ...pops(64, MUTED, 600), ...blurIn(t, 5.86) }}>Quando alguém parte</div></Row>
      <Row top={990}><div style={{ ...anton(210), ...slam(t, STOP) }}>de repente</div></Row>
      <Bar t={t} at={STOP + 0.15} w={760} top={1238} />
      <Row top={1320} style={{ gap: 28 }}>
        {[["num acidente", 7.86], ["sem aviso", 9.0]].map(([w, at]) => {
          const e = pop(t, at as number, 0.4);
          return (
            <div key={w as string} style={{ padding: "16px 34px", borderRadius: 16, border: `3px solid ${RED}`, ...pops(52, WHITE, 600), opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 60).toFixed(1)}px) scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>{w}</div>
          );
        })}
      </Row>
    </AbsoluteFill>
  );
};

// ───────── cena 2b · quem fica não tem a chance de se despedir: a mensagem que não chega ─────────
const Despedir: React.FC<{ t: number }> = ({ t }) => {
  const a = pop(t, T2B + 0.35, 0.45), b = pop(t, 11.2, 0.45);
  const fail = k(t, 12.04, 0.35);
  const cam = 1 + 0.05 * lin(t, T2B, T3);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Row top={330}><div style={{ ...anton(110), ...blurIn(t, 10.38) }}>Quem fica não tem</div></Row>
      <Row top={465}><div style={{ ...anton(110), ...blurIn(t, 11.04) }}>a chance de</div></Row>
      <Row top={600}><div style={{ ...anton(130, RED), ...slam(t, 11.92) }}>se despedir</div></Row>
      {/* conversa desenhada: a resposta fica sem entregar */}
      <div style={{ position: "absolute", left: 120, top: 960, width: 840, transform: `scale(${cam.toFixed(4)}) translateY(${(-lin(t, T2B, T3) * 30).toFixed(1)}px)`, transformOrigin: "50% 0%" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 34 }}>
          <div style={{ alignSelf: "flex-start", maxWidth: 640, padding: "30px 40px", borderRadius: "44px 44px 44px 12px", background: "#262626", ...pops(52, WHITE, 500), opacity: Math.min(1, a * 2), transform: `translateX(${((1 - a) * -120).toFixed(1)}px) scale(${(0.8 + 0.2 * a).toFixed(3)})`, transformOrigin: "0% 100%" }}>
            Te vejo mais tarde?
          </div>
          <div style={{ alignSelf: "flex-end", display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 14, opacity: Math.min(1, b * 2), transform: `translateX(${((1 - b) * 120).toFixed(1)}px) scale(${(0.8 + 0.2 * b).toFixed(3)})`, transformOrigin: "100% 100%" }}>
            <div style={{ padding: "30px 40px", borderRadius: "44px 44px 12px 44px", background: RED, ...pops(52, WHITE, 600), filter: `grayscale(${(fail * 0.85).toFixed(2)}) brightness(${(1 - fail * 0.35).toFixed(2)})` }}>
              Te amo. Até já!
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 12, ...pops(36, MUTED, 500) }}>
              {t < 12.04 ? (
                <>
                  <svg width={36} height={36} viewBox="0 0 24 24" fill="none" stroke={MUTED} strokeWidth={2.4} strokeLinecap="round"><circle cx={12} cy={12} r={9} /><path d={`M12 12V7`} transform={`rotate(${((t - 11.2) * 360).toFixed(0)} 12 12)`} /></svg>
                  <span>enviando…</span>
                </>
              ) : (
                <div style={{ display: "flex", alignItems: "center", gap: 12, opacity: fail, transform: `translateX(${(Math.sin((t - 12.04) * 50) * 10 * Math.max(0, 1 - (t - 12.04) / 0.4)).toFixed(1)}px)` }}>
                  <svg width={36} height={36} viewBox="0 0 24 24" fill="none" stroke={RED} strokeWidth={2.6} strokeLinecap="round"><circle cx={12} cy={12} r={9} /><path d="M12 7v6M12 16.5v.5" /></svg>
                  <span style={{ color: WHITE }}>não entregue</span>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// batimento desenhado da esquerda para a direita; os picos diminuem e a linha termina reta, some quando LUTO bate
const PULSE = (() => {
  const pts: string[] = ["M 0 0"];
  const beats = [120, 300, 470, 620];
  const amp = [1, 0.75, 0.45, 0.2];
  beats.forEach((x, i) => {
    const a = 150 * amp[i];
    pts.push(`L ${x} 0 L ${x + 18} ${-a * 0.25} L ${x + 34} 0 L ${x + 50} ${a * 0.35} L ${x + 66} ${-a} L ${x + 84} ${a * 0.6} L ${x + 100} 0`);
  });
  pts.push("L 840 0");
  return pts.join(" ");
})();
const Pulse: React.FC<{ t: number }> = ({ t }) => {
  const draw = interpolate(t, [T3 + 0.1, 15.2], [0, 1], cl);
  const o = 1 - lin(t, 15.25, 15.45);
  if (o <= 0) return null;
  return (
    <svg width={840} height={400} viewBox="0 -200 840 400" style={{ position: "absolute", left: 120, top: 560, opacity: o, overflow: "visible" }}>
      <path d={PULSE} fill="none" stroke={RED} strokeWidth={9} strokeLinejoin="round" strokeLinecap="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - draw} style={{ filter: "drop-shadow(0 0 14px rgba(243,22,22,0.55))" }} />
    </svg>
  );
};

// ───────── cena 3 · essa dor tem nome: luto. E pode ser ressignificada ─────────
const Luto: React.FC<{ t: number }> = ({ t }) => {
  const box = interpolate(t, [17.7, 18.05], [0, 1], { ...cl, easing: INOUT });
  const cam = 1 + 0.05 * lin(t, T3, T4);
  return (
    <AbsoluteFill style={{ background: BG }}>
      <Glow x={540} y={880} r={560} o={k(t, 15.36, 0.6) * (0.55 + 0.25 * Math.sin((t - 15.36) * 1.8))} />
      <Pulse t={t} />
      <Row top={440}><div style={{ ...pops(66, MUTED, 600), ...blurIn(t, 13.48) }}>Essa dor tem nome:</div></Row>
      <div style={{ position: "absolute", left: 0, right: 0, top: 560, display: "flex", justifyContent: "center", transform: `scale(${cam.toFixed(4)})` }}>
        <div style={{ ...anton(380), lineHeight: 1, ...slam(t, 15.36) }}>Luto</div>
      </div>
      <Bar t={t} at={15.5} w={640} top={970} h={22} />
      <Row top={1080}><div style={{ ...pops(64, WHITE, 600), ...blurIn(t, 16.5) }}>E ela pode ser</div></Row>
      <Row top={1190}>
        <div style={{ position: "relative", padding: "6px 30px 10px" }}>
          <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${(box * 100).toFixed(1)}%`, background: RED }} />
          <div style={{ position: "relative", ...anton(116), ...blurIn(t, 17.8, undefined, 0.35) }}>ressignificada</div>
        </div>
      </Row>
    </AbsoluteFill>
  );
};

// ───────── cena 4a · o livro ─────────
