export const LivroFisico: React.FC = () => {
  const t = useCurrentFrame() / LF_FPS - LEAD;
  // trocas, cada uma de um jeito: corte com faixa vermelha · desfoque · íris · empurrão lateral · folha que sobe ·
  // recuo · duas metades · círculo
  const band = interpolate(t, [T2 - 0.3, T2 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const blurT = interpolate(t, [T2B - 0.22, T2B + 0.22], [0, 1], { ...cl, easing: INOUT });
  const iris = interpolate(t, [T3 - 0.2, T3 + 0.3], [0, 1], { ...cl, easing: INOUT });
  const zoomT = interpolate(t, [T4 - 0.22, T4 + 0.24], [0, 1], { ...cl, easing: INOUT });
  const push = interpolate(t, [T4B - 0.25, T4B + 0.22], [0, 1], { ...cl, easing: INOUT });
  const sheet = interpolate(t, [T5 - 0.26, T5 + 0.22], [0, 1], { ...cl, easing: OUT });
  const fade = interpolate(t, [T5B - 0.2, T5B + 0.2], [0, 1], { ...cl, easing: INOUT });
  const split = interpolate(t, [T6 - 0.2, T6 + 0.24], [0, 1], { ...cl, easing: INOUT });
  const circ = interpolate(t, [T7 - 0.2, T7 + 0.32], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: BG }}>
      {t < T2 + 0.05 ? <Ligacao t={t} /> : null}
      {t >= T2 - 0.05 && t < T2B + 0.25 ? (
        <AbsoluteFill style={{ opacity: 1 - blurT, filter: `blur(${(blurT * 24).toFixed(1)}px)`, transform: `scale(${(1 + 0.15 * blurT).toFixed(4)})` }}><Repente t={t} /></AbsoluteFill>
      ) : null}
      {/* faixa vermelha inclinada cobre a troca da ligação para o relógio */}
      {t >= T2 - 0.3 && t < T2 + 0.3 ? (
        <div style={{ position: "absolute", left: 540 - 1000, top: -500, width: 2000, height: 2920, background: RED, transform: `rotate(-14deg) translateX(${((band - 0.5) * 2 * 2700).toFixed(1)}px)` }} />
      ) : null}
      {t >= T2B - 0.22 && t < T3 + 0.32 ? (
        <AbsoluteFill style={{ opacity: t < T2B + 0.25 ? blurT : 1, filter: t < T2B + 0.25 ? `blur(${((1 - blurT) * 24).toFixed(1)}px)` : undefined, transform: `scale(${(1.12 - 0.12 * blurT).toFixed(4)})` }}><Despedir t={t} /></AbsoluteFill>
      ) : null}
      {t >= T3 - 0.2 && t < T4 + 0.25 ? (
        <AbsoluteFill style={{ clipPath: t < T3 + 0.32 ? `circle(${(iris * 2300).toFixed(0)}px at 540px 960px)` : undefined, opacity: 1 - zoomT, transform: `scale(${(1 + 0.25 * zoomT).toFixed(4)})` }}><Luto t={t} /></AbsoluteFill>
      ) : null}
      {t >= T4 - 0.22 && t < T4B + 0.25 ? (
        <AbsoluteFill style={{ opacity: t < T4 + 0.25 ? zoomT : 1, transform: `translateX(${(-push * 1080).toFixed(1)}px)` }}><Livro t={t} /></AbsoluteFill>
      ) : null}
      {t >= T4B - 0.25 && t < T5 + 0.25 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px) scale(${(1 - 0.06 * sheet).toFixed(4)})` }}><Historias t={t} /></AbsoluteFill>
      ) : null}
      {t >= T5 - 0.26 && t < T5B + 0.22 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1920).toFixed(1)}px) scale(${(1 - 0.08 * fade).toFixed(4)})`, opacity: 1 - fade, borderRadius: `${((1 - sheet) * 90).toFixed(0)}px ${((1 - sheet) * 90).toFixed(0)}px 0 0`, overflow: "hidden", boxShadow: "0 -30px 80px rgba(0,0,0,0.6)" }}><Paginas t={t} /></AbsoluteFill>
      ) : null}
      {t >= T5B - 0.2 && t < T6 + 0.26 ? (
        <AbsoluteFill style={{ opacity: t < T5B + 0.22 ? fade : 1, transform: `scale(${(1.1 - 0.1 * fade).toFixed(4)})` }}><Bonus t={t} /></AbsoluteFill>
      ) : null}
      {t >= T6 - 0.2 && t < T7 + 0.34 ? (
        <AbsoluteFill style={{ clipPath: `inset(${((1 - split) * 50).toFixed(2)}% 0 ${((1 - split) * 50).toFixed(2)}% 0)` }}><Frete t={t} /></AbsoluteFill>
      ) : null}
      {t >= T7 - 0.2 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(circ * 2300).toFixed(0)}px at 540px 700px)` }}><Fecho t={t} /></AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

